class SiteHeader extends HTMLElement {
    connectedCallback() {
        this.innerHTML = '\n      <header class="site-header">\n        <div class="site-header__inner">\n          <a class="brand" href="index.html" aria-label="Raritan EWC 首頁">Raritan EWC</a>\n\n          <button class="nav-toggle" type="button" aria-expanded="false" aria-controls="primary-navigation">\n            <span class="sr-only">開啟導覽選單</span>\n            <span></span><span></span><span></span>\n          </button>\n\n          <nav id="primary-navigation" class="primary-nav" aria-label="主要導覽">\n            <a href="index.html">首頁</a>\n\n            <div class="nav-dropdown">\n             <button class="nav-dropdown__trigger" type="button" aria-expanded="false">福委會服務</button>\n              <div class="nav-dropdown__menu">\n                <a href="discount-vendors.html">特約商店清單</a>\n                <a href="amot-id.html">AMOT 特約企業識別</a>\n                <a href="pizza-hot.html">Pizza Hot 優惠碼</a>\n                <a href="kfc-breakfast.html">KFC 早餐優惠碼</a>\n                <a href="kfc-normal.html">KFC 正餐優惠碼</a>              \n              </div>\n            </div>      \n            <a href="charity_section.html">公益專區</a>\n            <a href="https://www.raritan.com/ap/tw" target="_blank" rel="noopener noreferrer">公司官網</a>\n          </nav>\n        </div>\n      </header>\n    ';
        const e = this.querySelector(".nav-toggle"), a = this.querySelector(".primary-nav"), t = this.querySelector(".nav-dropdown"),
            n = this.querySelector(".nav-dropdown__trigger");
        e.addEventListener("click", () => {
            const t = "true" === e.getAttribute("aria-expanded");
            e.setAttribute("aria-expanded", String(!t)), a.classList.toggle("is-open", !t)
        }), n.addEventListener("click", e => {
            e.stopPropagation();
            const a = "true" === n.getAttribute("aria-expanded");
            n.setAttribute("aria-expanded", String(!a)), t.classList.toggle("is-open", !a)
        }), document.addEventListener("click", e => {
            t.contains(e.target) || (t.classList.remove("is-open"), n.setAttribute("aria-expanded", "false"))
        }), window.addEventListener("resize", () => {
            window.innerWidth > 760 && (a.classList.remove("is-open"), e.setAttribute("aria-expanded", "false"))
        })
    }
}

class SiteFooter extends HTMLElement {
    connectedCallback() {
        this.innerHTML = '\n      <footer class="site-footer">\n        <p>Raritan EWC © <span data-copyright-year>2026</span></p>\n\n        <p class="footer-powered">\n          Powered by\n          <span class="footer-tooltip" data-tooltip="GitHub Pages">\n          <img src="assets/icon/github-icon.webp" alt="GitHub Logo">\n          </span>\n           & \n           <span class="footer-tooltip" data-tooltip="Google Apps Script">\n          <img src="assets/icon/google-apps-script.webp" alt="Google Sheets Logo">\n          </span> \n        </p>\n      </footer>\n    '
    }
}

customElements.define("site-header", SiteHeader), customElements.define("site-footer", SiteFooter);